-- src/alu.vhd
library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;
use work.cpu_package.all;

entity alu is
    port(
        op1         : in std_logic_vector(31 downto 0);
        op2         : in std_logic_vector(31 downto 0);
        op_type     : in ALU_OP_TYPE_t;
        result      : out std_logic_vector(31 downto 0)
    );
end alu;

architecture Behavioral of alu is
begin

    process(op1, op2, op_type)
        variable res_var : signed(31 downto 0);
    begin
        case op_type is
            when ALU_OP_TYPE_ADD =>
                result <= std_logic_vector(signed(op1) + signed(op2));
            when ALU_OP_TYPE_SUB =>
                result <= std_logic_vector(signed(op1) - signed(op2));
            when ALU_OP_TYPE_SLT =>
                res_var := '0' & signed(op1)(30 downto 0);
                if res_var < signed(op2) then
                    result <= x"00000001";
                else
                    result <= x"00000000";
                end if;
            when ALU_OP_TYPE_SLTU =>
                if unsigned(op1) < unsigned(op2) then
                    result <= x"00000001";
                else
                    result <= x"00000000";
                end if;
            when ALU_OP_TYPE_AND =>
                result <= op1 and op2;
            when ALU_OP_TYPE_OR =>
                result <= op1 or op2;
            when ALU_OP_TYPE_XOR =>
                result <= op1 xor op2;
            when ALU_OP_TYPE_SLL =>
                result <= std_logic_vector(shift_left(unsigned(op1), to_integer(unsigned(op2(4 downto 0)))));
            when ALU_OP_TYPE_SRL =>
                result <= std_logic_vector(shift_right(unsigned(op1), to_integer(unsigned(op2(4 downto 0)))));
            when ALU_OP_TYPE_SRA =>
                result <= std_logic_vector(shift_right(signed(op1), to_integer(unsigned(op2(4 downto 0)))));
            when others =>
                result <= (others => '0');
        end case;
    end process;

end Behavioral;
