-- REQ: FR-RV-04, FR-RV-05, FR-RV-06, FR-RV-12/FR-RV-13/FR-RV-14, FR-RV-15, FR-RV-16

library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.cpu_package.all;
use work.memory_package.all;

entity cpu_top is
    generic(
        ROM_INIT_FILE  : string  := "";
        ROM_SIZE_WORDS : integer := 0;
        RV32M_ENABLE   : boolean := false
    );
    port(
        rst : in std_logic;   -- asynchronous, ACTIVE HIGH
        clk : in std_logic
    );
end cpu_top;

architecture Behavioral of cpu_top is

    signal pc            : std_logic_vector(31 downto 0);
    signal instr         : std_logic_vector(31 downto 0);
    signal rd_addr1      : std_logic_vector(4 downto 0);
    signal rd_addr2      : std_logic_vector(4 downto 0);
    signal wr_addr       : std_logic_vector(4 downto 0);
    signal wr_data       : std_logic_vector(31 downto 0);
    signal wr_en         : std_logic;
    signal op_type       : ALU_OP_TYPE_t;
    signal branch_type   : BRANCH_TYPE_t;
    signal rd_data_source: RD_DATA_SOURCE_t;
    signal mem_access_width: MEM_ACCESS_WIDTH_t;
    signal pc_next_src   : PC_NEXT_SRC_t;
    signal alu_op1       : std_logic_vector(31 downto 0);
    signal alu_op2       : std_logic_vector(31 downto 0);
    signal alu_result    : std_logic_vector(31 downto 0);
    signal mem_write_enable: std_logic;
    signal data_in       : std_logic_vector(31 downto 0);
    signal data_out      : std_logic_vector(31 downto 0);
    signal m_dispatch    : std_logic;

begin

    -- Instantiate instruction memory
    instruction_memory_inst: entity work.instruction_memory
        generic map (
            ROM_INIT_FILE   => ROM_INIT_FILE,
            ROM_SIZE_WORDS  => ROM_SIZE_WORDS
        )
        port map (
            addr        => pc,
            instr       => instr
        );

    -- Instantiate data memory
    data_memory_inst: entity work.data_memory
        port map (
            clk                 => clk,
            addr                => alu_result,
            mem_write_enable    => mem_write_enable,
            access_width        => mem_access_width,
            data_in             => wr_data,
            data_out            => data_out
        );

    -- Instantiate register file
    register_file_inst: entity work.register_file
        port map (
            clk         => clk,
            rst         => rst,
            rd_addr1    => rd_addr1,
            rd_addr2    => rd_addr2,
            wr_addr     => wr_addr,
            wr_data     => alu_result,
            wr_en       => wr_en,
            data_out1   => alu_op1,
            data_out2   => alu_op2
        );

    -- Instantiate ALU
    alu_inst: entity work.alu
