use work.cpu_package.all;
use work.memory_package.all;

entity cpu_top is
    generic(
        ROM_INIT_FILE  : string  := "";
        ROM_SIZE_WORDS : integer := 0;
        RV32M_ENABLE   : boolean := false
    );
    port(
        rst : in std_logic;   -- asynchronous, ACTIVE HIGH
        clk : in std_logic
    );
end cpu_top;

architecture Behavioral of cpu_top is

    signal pc            : std_logic_vector(31 downto 0);
    signal instr         : std_logic_vector(31 downto 0);
    signal rd_addr1      : std_logic_vector(4 downto 0);
    signal rd_addr2      : std_logic_vector(4 downto 0);
    signal wr_addr       : std_logic_vector(4 downto 0);
    signal wr_data       : std_logic_vector(31 downto 0);
    signal wr_en         : std_logic;
    signal op_type       : ALU_OP_TYPE_t;
    signal branch_type   : BRANCH_TYPE_t;
    signal rd_data_source: RD_DATA_SOURCE_t;
    signal mem_access_width: MEM_ACCESS_WIDTH_t;
    signal pc_next_src   : PC_NEXT_SRC_t;
    signal alu_op1       : std_logic_vector(31 downto 0);
    signal alu_op2       : std_logic_vector(31 downto 0);
    signal alu_result    : std_logic_vector(31 downto 0);
    signal mem_write_enable: std_logic;
    signal data_in       : std_logic_vector(31 downto 0);
    signal data_out      : std_logic_vector(31 downto 0);
    signal m_dispatch    : std_logic;

begin

    -- Instantiate instruction memory
    instruction_memory_inst: entity work.instruction_memory
        generic map (
            ROM_INIT_FILE   => ROM_INIT_FILE,
            ROM_SIZE_WORDS  => ROM_SIZE_WORDS
        )
        port map (
            addr        => pc,
            instr       => instr
        );

    -- Instantiate data memory
    data_memory_inst: entity work.data_memory
        port map (
            clk                 => clk,
            addr                => alu_result,
            mem_write_enable    => mem_write_enable,
            access_width        => mem_access_width,
            data_in             => wr_data,
            data_out            => data_out
        );

    -- Instantiate register file
    register_file_inst: entity work.register_file
        port map (
            clk         => clk,
            rst         => rst,
            rd_addr1    => rd_addr1,
            rd_addr2    => rd_addr2,
            wr_addr     => wr_addr,
            wr_data     => alu_result,
            wr_en       => wr_en,
            data_out1   => alu_op1,
            data_out2   => alu_op2
        );

    -- Instantiate ALU
    alu_inst: entity work.alu
        port map (
            op1         => alu_op1,
            op2         => alu_op2,
            op_type     => op_type,
            result      => alu_result
        );

    -- Instantiate decoder
    decoder_inst: entity work.decoder
        port map (
            instr         => instr,
            rd_addr1      => rd_addr1,
            rd_addr2      => rd_addr2,
            wr_addr       => wr_addr,
            wr_en         => wr_en,
            op_type       => op_type,
            branch_type   => branch_type,
            rd_data_source=> rd_data_source,
            mem_access_width=> mem_access_width,
            pc_next_src   => pc_next_src
        );

    -- Instantiate M extension unit if enabled
    m_dispatch <= '1' when RV32M_ENABLE and is_rv32m_op(op_type) else '0';
    mul_div_unit_inst: entity work.mul_div_unit
        port map (
            op1         => alu_op1,
            op2         => alu_op2,
            op_type     => op_type,
            start       => m_dispatch,
            res         => alu_result,
            busy        => open
        );

    -- PC logic
    pc_process: process(clk, rst)
    begin
        if rst = '1' then
            pc <= std_logic_vector(to_unsigned(RESET_HANDLER_ADDRESS, 32));
        elsif rising_edge(clk) then
            case pc_next_src is
                when PC_NEXT_SRC_PC_ALU_RES =>
                    pc <= alu_result;
                when PC_NEXT_SRC_PC_IMM =>
                    pc <= std_logic_vector(unsigned(pc) + unsigned(alu_op1));
                when PC_NEXT_SRC_PC_4 =>
                    pc <= std_logic_vector(unsigned(pc) + 4);
            end case;
        end if;
    end process;

    -- Memory write enable logic
    mem_write_enable <= '1' when rd_data_source = RD_DATA_SOURCE_MEM_DATA_OUT else '0';

    -- Data in selection logic
    data_in_process: process(rd_data_source, alu_result, pc)
    begin
        case rd_data_source is
            when RD_DATA_SOURCE_PC_IMM =>
                data_in <= std_logic_vector(unsigned(pc) + unsigned(alu_op1));
            when RD_DATA_SOURCE_PC_4 =>
                data_in <= std_logic_vector(unsigned(pc) + 4);
            when others =>
                data_in <= alu_result;
        end case;
    end process;

end Behavioral;
